/**
 * Suspending and reinstating members, and what a suspension changes elsewhere:
 * actor resolution, seats, notifications, assignment and mentions.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { NotFoundError } from "@/server/services/_support";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import { buildDigest, listDigestRecipients } from "@/server/services/digest-service";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { MemberSuspendedError } from "@/server/services/member-service";
import { listNotifications, notify } from "@/server/services/notification-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { activityFilterSchema } from "@/schemas/activity";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { MemberId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Member, Role } from "@/types/member";

let cleanup: () => void;
let detachActivity: Unsubscribe;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function memberFor(tenant: Tenant, role: Role): Promise<Member> {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error(`fixture ${role} missing`);
  return member;
}

async function suspend(tenant: Tenant, role: Role): Promise<Member> {
  const target = await memberFor(tenant, role);
  return memberService.suspendMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: target.id,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachActivity = registerActivityListeners();
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachActivity();
  cleanup();
});

describe("suspendMember / reinstateMember", () => {
  it("suspends and reinstates, publishing and auditing each change", async () => {
    const tenant = await createTenant("suspend-basic");
    const target = await memberFor(tenant, "member");
    const suspendedEvents = capture("member.suspended");
    const reinstatedEvents = capture("member.reinstated");

    const suspended = await memberService.suspendMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(suspended.status).toBe("suspended");
    expect(suspended.role).toBe("member");
    expect(suspendedEvents).toHaveLength(1);
    expect(suspendedEvents[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      memberId: target.id,
      userId: tenant.userIds.member,
    });

    const reinstated = await memberService.reinstateMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(reinstated.status).toBe("active");
    expect(reinstatedEvents).toHaveLength(1);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "member",
      target.id,
    );
    expect(audit.map((row) => row.action).sort()).toEqual([
      "member.reinstated",
      "member.suspended",
    ]);
    for (const row of audit) expect(row.actorId).toBe(tenant.userIds.admin);
  });

  it("accepts the new actions in audit-log filters", () => {
    const parsed = activityFilterSchema.parse({
      orgId: "org-1",
      action: ["member.suspended", "member.reinstated"],
      limit: 10,
      cursor: null,
    });
    expect(parsed.action).toEqual(["member.suspended", "member.reinstated"]);
  });

  it("is a silent no-op when nothing would change", async () => {
    const tenant = await createTenant("suspend-noop");
    const target = await memberFor(tenant, "viewer");

    const untouched = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(untouched).toEqual(target);

    await suspend(tenant, "viewer");
    const events = capture("member.suspended");
    const again = await suspend(tenant, "viewer");
    expect(again.status).toBe("suspended");
    expect(events).toHaveLength(0);
  });

  it("guards scope, existence and permission", async () => {
    const tenant = await createTenant("suspend-guards");
    const other = await createTenant("suspend-guards-other");
    const target = await memberFor(tenant, "viewer");

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: other.org.id,
        memberId: target.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: "nope" as MemberId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.suspendMember(tenant.actors.member, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toThrow();

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses self-suspension and suspending a higher role", async () => {
    const tenant = await createTenant("suspend-rank");
    const events = capture("member.suspended");
    const admin = await memberFor(tenant, "admin");
    const owner = await memberFor(tenant, "owner");

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: admin.id,
      }),
    ).rejects.toThrow();
    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow();

    expect(events).toHaveLength(0);
    expect((await memberFor(tenant, "admin")).status).toBe("active");
    expect((await memberFor(tenant, "owner")).status).toBe("active");

    const suspendedAdmin = await suspend(tenant, "admin");
    expect(suspendedAdmin.status).toBe("suspended");
  });

  it("keeps at least one owner who is not suspended", async () => {
    const tenant = await createTenant("suspend-owners");
    const owner = await memberFor(tenant, "owner");
    const admin = await memberFor(tenant, "admin");

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "owner",
    });
    const secondOwner = { ...tenant.actors.admin, role: "owner" as const };

    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });

    // The first owner is now the only one not suspended.
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);
    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow(/at least one owner/);
    await expect(
      memberService.suspendMember(secondOwner, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow(/at least one owner/);
    expect((await memberFor(tenant, "owner")).status).toBe("active");
  });
});

describe("while suspended", () => {
  it("cannot act, and drops out of the org switcher", async () => {
    const tenant = await createTenant("suspend-actor");
    await suspend(tenant, "member");

    await expect(
      memberService.resolveActor(tenant.userIds.member, tenant.org.id),
    ).resolves.toBeNull();
    const orgs = await orgRepo.listOrgsForUser(tenant.userIds.member);
    expect(orgs.map((org) => org.id)).not.toContain(tenant.org.id);

    const listed = await memberService.listMembers(tenant.actors.owner, {
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    const row = listed.items.find((m) => m.userId === tenant.userIds.member);
    expect(row?.status).toBe("suspended");

    const target = await memberFor(tenant, "member");
    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    await expect(
      memberService.resolveActor(tenant.userIds.member, tenant.org.id),
    ).resolves.toMatchObject({ role: "member" });
    const after = await orgRepo.listOrgsForUser(tenant.userIds.member);
    expect(after.map((org) => org.id)).toContain(tenant.org.id);
  });

  it("keeps their seat", async () => {
    const tenant = await createTenant("suspend-seat");
    await suspend(tenant, "viewer");

    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(4);
    const usage = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.seatsUsed).toBe(4);
    const summary = await getOrganizationSummary(tenant.actors.owner, tenant.org.id);
    expect(summary.memberCount).toBe(4);

    const viewer = await memberFor(tenant, "viewer");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(3);
  });

  it("receives no notifications and no digest", async () => {
    const tenant = await createTenant("suspend-notify");
    await preferenceRepo.upsertPreference({
      orgId: tenant.org.id,
      userId: tenant.userIds.viewer,
      kind: "comment_mention",
      inApp: true,
      email: true,
      digestOnly: true,
    });
    await notify(tenant.org.id, "comment_mention", [tenant.userIds.viewer], {
      title: "Before",
      body: "before suspension",
      href: "/x",
      actorId: tenant.userIds.owner,
    });

    await suspend(tenant, "viewer");

    const created = await notify(
      tenant.org.id,
      "comment_mention",
      [tenant.userIds.viewer, tenant.userIds.member],
      { title: "During", body: "during", href: "/x", actorId: tenant.userIds.owner },
    );
    expect(created.map((row) => row.recipientId)).toEqual([tenant.userIds.member]);

    expect(await listDigestRecipients(tenant.org.id)).not.toContain(
      tenant.userIds.viewer,
    );
    const now = new Date();
    const windowStart = toIsoTimestamp(new Date(now.getTime() - 60 * 60 * 1000));
    const windowEnd = toIsoTimestamp(new Date(now.getTime() + 60 * 1000));
    await expect(
      buildDigest(tenant.org.id, tenant.userIds.viewer, windowStart, windowEnd),
    ).resolves.toBeNull();

    const viewer = await memberFor(tenant, "viewer");
    await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });
    expect(await listDigestRecipients(tenant.org.id)).toContain(tenant.userIds.viewer);

    const unread = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.viewer,
      unreadOnly: true,
      limit: 50,
      cursor: null,
    });
    expect(unread.items.map((row) => row.title)).toEqual(["Before"]);
  });

  it("cannot be handed new work", async () => {
    const tenant = await createTenant("suspend-assign");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.admin }),
    );
    await suspend(tenant, "admin");

    const created = capture("issue.created");
    const assigned = capture("issue.assigned");
    const before = await issueRepo.countIssues(tenant.org.id, tenant.project.id);

    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, {
          title: "Nope",
          assigneeId: tenant.userIds.admin,
        }),
      ),
    ).rejects.toBeInstanceOf(MemberSuspendedError);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(
      before,
    );

    const other = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Other issue" }),
    );
    await expect(
      issueService.assignIssue(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: other.id,
        assigneeId: tenant.userIds.admin,
      }),
    ).rejects.toMatchObject({ code: "conflict" });
    expect(created).toHaveLength(1);
    expect(assigned).toHaveLength(0);

    // Existing assignments stay; un-assigning still works.
    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.assigneeId).toBe(tenant.userIds.admin);
    const unassigned = await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });
    expect(unassigned.assigneeId).toBeNull();
  });

  it("cannot be mentioned", async () => {
    const tenant = await createTenant("suspend-mention");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id),
    );
    await suspend(tenant, "viewer");
    const events = capture("comment.created");

    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "cc @viewer and @admin",
      parentId: null,
      mentionedUserIds: [tenant.userIds.viewer],
    });

    expect(comment.mentionedUserIds).toEqual([tenant.userIds.admin]);
    expect(events[0]?.mentionedUserIds).toEqual([tenant.userIds.admin]);
  });
});

