describe("suspendMember / reinstateMember", () => {
  it("suspends and reinstates, publishing and auditing each change", async () => {
    const tenant = await createTenant("suspend-basic");
    const target = await memberFor(tenant, "member");
    const suspendedEvents = capture("member.suspended");
    const reinstatedEvents = capture("member.reinstated");

    const suspended = await memberService.suspendMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(suspended.status).toBe("suspended");
    expect(suspended.role).toBe("member");
    expect(suspendedEvents).toHaveLength(1);
    expect(suspendedEvents[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      memberId: target.id,
      userId: tenant.userIds.member,
    });

    const reinstated = await memberService.reinstateMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(reinstated.status).toBe("active");
    expect(reinstatedEvents).toHaveLength(1);

    const audit = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "member",
      target.id,
    );
    expect(audit.map((row) => row.action).sort()).toEqual([
      "member.reinstated",
      "member.suspended",
    ]);
    for (const row of audit) expect(row.actorId).toBe(tenant.userIds.admin);
  });

  it("accepts the new actions in audit-log filters", () => {
    const parsed = activityFilterSchema.parse({
      orgId: "org-1",
      action: ["member.suspended", "member.reinstated"],
      limit: 10,
      cursor: null,
    });
    expect(parsed.action).toEqual(["member.suspended", "member.reinstated"]);
  });

  it("is a silent no-op when nothing would change", async () => {
    const tenant = await createTenant("suspend-noop");
    const target = await memberFor(tenant, "viewer");

    const untouched = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(untouched).toEqual(target);

    await suspend(tenant, "viewer");
    const events = capture("member.suspended");
    const again = await suspend(tenant, "viewer");
    expect(again.status).toBe("suspended");
    expect(events).toHaveLength(0);
  });

  it("guards scope, existence and permission", async () => {
    const tenant = await createTenant("suspend-guards");
    const other = await createTenant("suspend-guards-other");
    const target = await memberFor(tenant, "viewer");

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: other.org.id,
        memberId: target.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: "nope" as MemberId,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.suspendMember(tenant.actors.member, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toThrow();

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.reinstateMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses self-suspension and suspending a higher role", async () => {
    const tenant = await createTenant("suspend-rank");
    const events = capture("member.suspended");
    const admin = await memberFor(tenant, "admin");
    const owner = await memberFor(tenant, "owner");

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: admin.id,
      }),
    ).rejects.toThrow();
    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: owner.id,
      }),
    ).rejects.toThrow();

    expect(events).toHaveLength(0);
    expect((await memberFor(tenant, "admin")).status).toBe("active");
    expect((await memberFor(tenant, "owner")).status).toBe("active");

    const suspendedAdmin = await suspend(tenant, "admin");
    expect(suspendedAdmin.status).toBe("suspended");
  });

  it("keeps at least one owner who is not suspended", async () => {
    const tenant = await createTenant("suspend-owners");
    const owner = await memberFor(tenant, "owner");
    const admin = await memberFor(tenant, "admin");

    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
      role: "owner",
    });
    const secondOwner = { ...tenant.actors.admin, role: "owner" as const };

    await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });

    // The first owner is now the only one not suspended.
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: owner.id,
