/**
 * Locks a member out without removing them: they keep their membership, role
 * and seat. Suspending someone already suspended is a no-op.
 */
export async function suspendMember(
  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  const member = await loadSuspensionTarget(actor, input);
  if (member.status === "suspended") return member;

  if (member.role === "owner") {
    await assertAnotherOwnerRemains(input.orgId, member.id);
  }

  const suspended = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Lifts a suspension. Reinstating a member who is not suspended is a no-op. */
export async function reinstateMember(
  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  const member = await loadSuspensionTarget(actor, input);
  if (member.status !== "suspended") return member;

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/**
 * Throws `MemberSuspendedError` when `userId` is a suspended member of the
 * org. Called before any write that hands work to someone.
 */
export async function assertNotSuspended(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, userId);
  if (member && isSuspended(member)) {
    throw new MemberSuspendedError(userId);
  }
}

/**
 * The guards suspension and reinstatement share, in the same spirit as
 * removal: tenant scope, a live member, `member:remove` on them — and two rules
 * the matrix cannot express: nobody acts on themselves, and nobody acts on a
 * member whose role outranks their own.
 */
async function loadSuspensionTarget(
  actor: Actor,
  input: MemberSuspensionInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const found = await memberRepo.findMemberById(input.orgId, input.memberId);
  const member = requireFound(
    found && isLive(found) ? found : null,
    "Member",
    input.memberId,
  );
  const resource = memberResource(member);
  assertCan(actor, "member:remove", resource);

  if (member.userId === actor.userId || !hasRoleAtLeast(actor.role, member.role)) {
    throw new PermissionDeniedError("member:remove", {
      allowed: false,
      action: "member:remove",
      resourceKind: resource.kind,
      reason: "denied_by_role",
    });
  }

  return member;
}

